const __pageData = JSON.parse('{"title":"3.15 Tumble Transport Dumper","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Creative Building & Styling/3.15 Tumble Transport Dumper.md","filePath":"docs/3. Creative Building & Styling/3.15 Tumble Transport Dumper.md"}');
